contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address _log, uint _val) public payable {
        require(true);

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetLogFile(_log); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted);
    }
}

